using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
var app = builder.Build();
app.MapControllers();
app.Run();

namespace VulnApp.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DiagnosticsController : ControllerBase
    {
        // Endpoint for generating formatted diagnostic reports
        [HttpPost("report")]
        public IActionResult GenerateReport([FromBody] ReportRequest request)
        {
            try
            {
                // Build diagnostic info using user-supplied format template
                var timestamp = DateTime.UtcNow.ToString("o");
                var hostname = Environment.MachineName;
                var pid = Process.GetCurrentProcess().Id;

                // VULNERABILITY: User-controlled format string passed to String.Format
                // In .NET, format strings can cause DoS via index out of range,
                // but the real danger is the subsequent native interop call
                string formattedOutput = string.Format(request.Template, 
                    timestamp, hostname, pid, request.ClientId);

                // Log to native syslog for audit trail
                LogToNativeSyslog(request.Priority, formattedOutput);

                return Ok(new { report = formattedOutput, status = "logged" });
            }
            catch (FormatException ex)
            {
                return BadRequest(new { error = "Invalid format", detail = ex.Message });
            }
        }

        [HttpPost("exec-diagnostic")]
        public IActionResult ExecDiagnostic([FromBody] DiagRequest request)
        {
            try
            {
                // Format the command template with safe parameters
                string command = string.Format(request.CommandTemplate,
                    Environment.MachineName, DateTime.UtcNow.Ticks);

                // Execute network diagnostic (ping, traceroute, etc.)
                var psi = new ProcessStartInfo
                {
                    FileName = "/bin/sh",
                    Arguments = $"-c \"{command}\"",
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false
                };

                using var process = Process.Start(psi);
                process.WaitForExit(5000);
                var output = process.StandardOutput.ReadToEnd();
                var error = process.StandardError.ReadToEnd();

                return Ok(new { output, error, exitCode = process.ExitCode });
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = ex.Message });
            }
        }

        // Native interop for syslog - uses format string directly
        [DllImport("libc", EntryPoint = "syslog")]
        private static extern void NativeSyslog(int priority, string format);

        private void LogToNativeSyslog(int priority, string message)
        {
            // Pass formatted message to native syslog
            // If message contains %n, %x, %s etc., native syslog interprets them
            NativeSyslog(priority, message);
        }
    }

    public class ReportRequest
    {
        public string Template { get; set; }
        public string ClientId { get; set; }
        public int Priority { get; set; } = 6; // LOG_INFO
    }

    public class DiagRequest
    {
        public string CommandTemplate { get; set; }
    }
}
